import{_ as e,o as n,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"About Rupa","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),r={name:"about.md"};function s(o,a,u,m,p,l){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="about-rupa" tabindex="-1">About Rupa <a class="header-anchor" href="#about-rupa" aria-label="Permalink to &quot;About Rupa&quot;">​</a></h1><p>Rupa berawal dari eksperimen membangun sistem komponen untuk proyek berbasis NextJS. Pada fase awal, pendekatan tersebut dibangun di atas NodeJS dan menggunakan aturan untuk membentuk komponen.</p><p>Dari eksperimen itu lahir konsep <strong>Ghost Component</strong>: ide untuk menyediakan banyak komponen dari konfigurasi tanpa harus membuat banyak berkas secara manual. Eksperimen tersebut mendorong pengembangan ke arah sistem yang lebih reaktif, tetapi keterbatasan fondasi awal membuat arah proyek terus berubah.</p><p>Tahap berikutnya adalah percobaan membuat DSL dengan C sebagai bagian dari toolchain proyek sebelumnya. Setelah fondasi dan kebutuhan sistem semakin berbeda dari lingkungan asalnya, keputusan akhirnya adalah membangun bahasa sendiri dari nol: Rupa.</p><h2 id="perjalanan-singkat" tabindex="-1">Perjalanan singkat <a class="header-anchor" href="#perjalanan-singkat" aria-label="Permalink to &quot;Perjalanan singkat&quot;">​</a></h2><ol><li>Rupa berawal dari eksperimen pendukung komponen berbasis NodeJS/NextJS.</li><li>Konsep Ghost Component menjadi salah satu inspirasi desain penting.</li><li>Kebutuhan reaktivitas dan performa mendorong eksperimen DSL.</li><li>DSL awal dibangun menggunakan C.</li><li>Fondasi proyek berkembang melampaui kebutuhan sistem sebelumnya.</li><li>Rupa kemudian dibangun sebagai bahasa pemrograman mandiri.</li></ol><p>Dokumen ini menjelaskan latar belakang, bukan spesifikasi teknis. Untuk implementasi dan kontribusi, lihat <a href="./instruction.html">instruction.md</a> dan <a href="./syntax/">syntax/</a>.</p>',7)])])}const d=e(r,[["render",s]]);export{k as __pageData,d as default};
